sys_script.script:
// Decrement available count when a book request is submitted
// Prevents the request if no copies are available (count = 0)
var bookRef = current.getValue('u_book_name');
if (bookRef) {
    var book = new GlideRecord('u_books');
    if (book.get(bookRef)) {
        var availableCount = parseInt(book.getValue('u_availabe_count'), 10);
        if (isNaN(availableCount)) {
            availableCount = 0;
        }
        if (availableCount <= 0) {
            gs.addErrorMessage('Cannot submit request: No copies of this book are currently available.');
            current.setAbortAction(true);
        } else {
            // Decrement the available count by 1
            book.setValue('u_availabe_count', availableCount - 1);
            book.update();
            // Update the displayed available count on the request record
            current.setValue('u_available_count', availableCount - 1);
        }
    } else {
        gs.addErrorMessage('Cannot submit request: The selected book was not found.');
        current.setAbortAction(true);
    }
}
